import { Component, ElementRef, inject, viewChildren } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatRippleModule } from '@angular/material/core';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { RouterLink } from '@angular/router';
import {
    IconComponent,
    LoadErrorComponent,
    TranslatePipe,
} from '@placeos/components';
import { SignageTemplate } from '@placeos/ts-client';
import { IntersectDirective } from '../shared/intersect.directive';
import { PlaylistStatusBadgeComponent } from '../shared/playlist-status-badge.component';
import { scrollSelectionIntoView } from '../shared/scroll-selection.util';
import { SignageTemplateService } from './signage-template.service';

type TemplateStatus = 'awaiting_approval' | 'awaiting_review' | null;

@Component({
    selector: 'template-list',
    template: `
        <div
            class="bg-base-100 border-base-300 h-full min-w-64 overflow-auto border-r sm:max-w-80"
        >
            <div
                class="border-base-300 bg-base-100 sticky top-0 z-10 border-b p-2"
            >
                <mat-form-field
                    appearance="outline"
                    class="no-subscript w-full"
                >
                    <input
                        matInput
                        [placeholder]="
                            'SIGNAGE_MANAGER.SEARCH_TEMPLATES' | translate
                        "
                        [(ngModel)]="search"
                        [attr.aria-label]="
                            'SIGNAGE_MANAGER.SEARCH_TEMPLATES' | translate
                        "
                    />
                </mat-form-field>
            </div>
            @if (templates().length > 0) {
                @for (template of templates(); track template.id) {
                    <a
                        #template_item
                        matRipple
                        class="border-base-300 relative z-0 flex w-full cursor-pointer items-center gap-3 border-b px-2 py-2 text-left no-underline transition-colors"
                        [class.bg-primary]="selected()?.id === template.id"
                        [class.text-primary-content]="
                            selected()?.id === template.id
                        "
                        [class.hover:bg-base-200]="
                            selected()?.id !== template.id
                        "
                        [routerLink]="['/templates', template.id]"
                        queryParamsHandling="merge"
                        [attr.aria-label]="
                            'SIGNAGE_MANAGER.OPEN_TEMPLATE'
                                | translate: { name: template.name }
                        "
                    >
                        <icon class="shrink-0 text-3xl opacity-60"
                            >dashboard_customize</icon
                        >
                        <div class="min-w-0 flex-1 pr-2">
                            <div class="truncate font-medium">
                                {{ template.name }}
                            </div>
                            <div
                                class="flex flex-wrap gap-1 text-[0.625rem] font-medium uppercase"
                            >
                                <span
                                    class="bg-base-200 text-base-content shrink-0 rounded px-1.5 py-0.5"
                                >
                                    {{
                                        'SIGNAGE_MANAGER.TEMPLATE_LAYOUT_COUNT'
                                            | translate
                                                : {
                                                      count: template.layouts
                                                          .length,
                                                  }
                                    }}
                                </span>
                                <playlist-status-badge
                                    [status]="getStatus(template)"
                                />
                            </div>
                            @if (template.description) {
                                <div
                                    class="mt-0.5 truncate text-xs"
                                    [class.opacity-70]="
                                        selected()?.id !== template.id
                                    "
                                    [class.opacity-90]="
                                        selected()?.id === template.id
                                    "
                                >
                                    {{ template.description }}
                                </div>
                            }
                            @if (template.shared_with.length) {
                                <div
                                    class="mt-0.5 flex min-w-0 items-center gap-1 text-xs"
                                    [class.opacity-70]="
                                        selected()?.id !== template.id
                                    "
                                    [class.opacity-90]="
                                        selected()?.id === template.id
                                    "
                                    [title]="sharedGroupNames(template)"
                                >
                                    <icon class="shrink-0 text-base"
                                        >groups</icon
                                    >
                                    <span class="shrink-0">
                                        {{
                                            'SIGNAGE_MANAGER.SHARED_WITH'
                                                | translate
                                        }}:
                                    </span>
                                    <span class="truncate">
                                        {{ sharedGroupNames(template) }}
                                    </span>
                                </div>
                            }
                        </div>
                    </a>
                }
                @if (has_more()) {
                    <div
                        class="h-px w-full"
                        intersect
                        (intersect)="loadMore()"
                    ></div>
                } @else if (error()) {
                    <load-error (retry)="reload()" />
                } @else {
                    <div
                        class="text-base-content/50 bg-base-content/10 col-span-full my-2 p-2 text-center text-xs"
                    >
                        {{ 'COMMON.END_OF_LIST' | translate }}
                    </div>
                }
            } @else if (loading()) {
                <div
                    class="text-base-content/70 flex flex-1 flex-col items-center justify-center space-y-3 p-8"
                >
                    <mat-spinner diameter="32" />
                    <p>{{ 'COMMON.LOADING' | translate }}</p>
                </div>
            } @else if (error()) {
                <load-error class="flex-1" (retry)="reload()" />
            } @else {
                <div
                    class="text-base-content/70 flex flex-1 flex-col items-center justify-center space-y-2 p-8"
                >
                    <icon class="text-6xl">dashboard_customize</icon>
                    <p>{{ 'SIGNAGE_MANAGER.NO_TEMPLATES' | translate }}</p>
                </div>
            }
        </div>
    `,
    styles: [
        `
            :host {
                display: flex;
                flex-direction: column;
                height: 100%;
            }
        `,
    ],
    imports: [
        PlaylistStatusBadgeComponent,
        FormsModule,
        RouterLink,
        MatRippleModule,
        MatFormFieldModule,
        MatInputModule,
        MatProgressSpinnerModule,
        IconComponent,
        LoadErrorComponent,
        TranslatePipe,
        IntersectDirective,
    ],
})
export class TemplateListComponent {
    private readonly _template_service = inject(SignageTemplateService);
    private readonly _template_items =
        viewChildren<ElementRef<HTMLAnchorElement>>('template_item');

    public readonly search = this._template_service.template_search_term;
    public readonly templates = this._template_service.templates;
    public readonly selected = this._template_service.selected_template;
    public readonly loading = this._template_service.templates_loading;
    public readonly error = this._template_service.templates_error;

    // Backend pagination: fetches the next page as the sentinel scrolls in.
    public readonly has_more = this._template_service.templates_has_more;

    constructor() {
        scrollSelectionIntoView(
            this.templates,
            this._template_items,
            this.selected,
        );
    }

    public loadMore() {
        this._template_service.loadMoreTemplates();
    }

    public reload() {
        this._template_service.reloadTemplates();
    }

    public getStatus(template: SignageTemplate): TemplateStatus {
        if (template.approved) return null;
        return template.approval_requested
            ? 'awaiting_review'
            : 'awaiting_approval';
    }

    public sharedGroupNames(template: SignageTemplate) {
        return template.shared_with.map(({ name }) => name).join(', ');
    }
}
